[CommandMethod("RCBOM")]
public void GenerateBOM()
{
    Document doc = Application.DocumentManager.MdiActiveDocument;
    Database db = doc.Database;
    Editor ed = doc.Editor;

    using (Transaction tr = db.TransactionManager.StartTransaction())
    {
        // Select assembly components
        var selection = ed.GetSelection();
        var components = ProcessAssembly(selection, tr);

        // Generate BOM with intelligent grouping
        var bom = new BillOfMaterials(components);
        bom.GroupBySimilarity();
        bom.CalculateQuantities();

        // Export to Excel
        var exporter = new XlsAgent();
        exporter.ExportBOM(bom, "Assembly_BOM.xlsx");

        tr.Commit();
    }
}

