[CommandMethod("RCAUTODIM")]
public void AutoDimension()
{
    Document doc = Application.DocumentManager.MdiActiveDocument;
    Database db = doc.Database;
    Editor ed = doc.Editor;

    using (Transaction tr = db.TransactionManager.StartTransaction())
    {
        // Get user selection
        PromptSelectionResult psr = ed.GetSelection();
        if (psr.Status != PromptStatus.OK) return;

        foreach (ObjectId id in psr.Value.GetObjectIds())
        {
            Entity ent = tr.GetObject(id, OpenMode.ForRead) as Entity;
            if (ent is Polyline pline)
            {
                // Auto-generate dimensions for each segment
                GenerateDimensionsForPolyline(pline, tr);
            }
        }
        tr.Commit();
    }
}

public class XlsAgent : IProcessingAgent
{
    private readonly BackgroundWorker _worker;

    public void ExportBOM(BillOfMaterials bom, string path)
    {
        _worker.RunWorkerAsync(new ExportJob
        {
            BOM = bom,
            OutputPath = path,
            Format = ExportFormat.Excel
        });
    }

    private void DoWork(object sender, DoWorkEventArgs e)
    {
        var job = e.Argument as ExportJob;
        using (var package = new ExcelPackage())
        {
            var ws = package.Workbook.Worksheets.Add("BOM");
            ws.Cells.LoadFromCollection(job.BOM.Items);
            package.SaveAs(new FileInfo(job.OutputPath));
        }
    }
}
